extern printf(fmt: string, ...);

frame main() ret int {
    local numbers: int[5] = [10, 20, 30, 40, 50];
    local length: int = 5;  # Track array length

    # Print all elements with a for loop
    printf("All numbers:\n");
    loop (local i: int = 0; i < length; i = i + 1) {
        printf("numbers[%d] = %d\n", i, numbers[i]);
    }

    # Calculate sum
    local sum: int = 0;
    loop (local j: int = 0; j < length; j = j + 1) {
        sum = sum + numbers[j];
    }
    printf("\nSum: %d\n", sum);
    printf("Average: %d\n", sum / length);

    # Find maximum
    local max: int = numbers[0];
    loop (local k: int = 1; k < length; k = k + 1) {
        if (numbers[k] > max) {
            max = numbers[k];
        }
    }
    printf("Maximum: %d\n", max);

    return 0;
}

