# Function that takes array and its length
frame printArray(arr: *int, len: int) {
    loop (local i: int = 0; i < len; i = i + 1) {
        printf("%d ", *(arr + i));
    }
    printf("\n");
}

# Function to calculate sum
frame sumArray(arr: *int, len: int) ret int {
    local total: int = 0;
    loop (local i: int = 0; i < len; i = i + 1) {
        total = total + *(arr + i);
    }
    return total;
}

# Function to find minimum
frame minArray(arr: *int, len: int) ret int {
    local min: int = *arr;  # First element
    loop (local i: int = 1; i < len; i = i + 1) {
        if (*(arr + i) < min) {
            min = *(arr + i);
        }
    }
    return min;
}

frame main() ret int {
    local data: int[5] = [42, 17, 89, 23, 56];
    local len: int = 5;

    printf("Array: ");
    printArray(&data[0], len);  # Pass pointer to first element

    printf("Sum: %d\n", sumArray(&data[0], len));
    printf("Min: %d\n", minArray(&data[0], len));

    return 0;
}

