# Safe getter with bounds checking
frame safeGet(arr: *int, len: int, index: int, defaultVal: int) ret int {
    if (index < 0 || index >= len) {
        printf("Warning: Index %d out of bounds (0-%d)\n", index, len - 1);
        return defaultVal;
    }
    return *(arr + index);
}

# Safe setter with bounds checking
frame safeSet(arr: *int, len: int, index: int, value: int) ret bool {
    if (index < 0 || index >= len) {
        printf("Error: Cannot set index %d (out of bounds)\n", index);
        return false;
    }
    *(arr + index) = value;
    return true;
}

frame main() ret int {
    local data: int[5] = [10, 20, 30, 40, 50];
    local len: int = 5;

    # Safe access
    printf("data[2]: %d\n", safeGet(&data[0], len, 2, 0));
    printf("data[10]: %d\n", safeGet(&data[0], len, 10, -1));

    # Safe modification
    safeSet(&data[0], len, 1, 25);
    printf("Updated data[1]: %d\n", safeGet(&data[0], len, 1, 0));

    safeSet(&data[0], len, 100, 999);  # Will fail safely

    return 0;
}

