extern printf(fmt: string, ...);

frame main() ret int {
    local scores: int[6] = [78, 92, 85, 69, 95, 88];
    local len: int = 6;

    local min: int = scores[0];
    local max: int = scores[0];
    local sum: int = 0;
    local passing: int = 0;

    loop (local i: int = 0; i < len; i = i + 1) {
        local score: int = scores[i];
        sum = sum + score;

        if (score < min) { min = score; }
        if (score > max) { max = score; }
        if (score >= 80) { passing = passing + 1; }
    }

    printf("Statistics:\n");
    printf("Min: %d\n", min);
    printf("Max: %d\n", max);
    printf("Sum: %d\n", sum);
    printf("Average: %d\n", sum / len);
    printf("Passing (>=80): %d out of %d\n", passing, len);

    return 0;
}
